$ErrorActionPreference = 'Stop'
$target = Join-Path (Get-Location) 'src\pages\SettingsPage.jsx'
$payload = @'

'@
$bytes = [Convert]::FromBase64String(($payload -replace '\s',''))
$input = New-Object System.IO.MemoryStream(,$bytes)
$gzip = New-Object System.IO.Compression.GzipStream($input,[System.IO.Compression.CompressionMode]::Decompress)
$output = New-Object System.IO.MemoryStream
$gzip.CopyTo($output)
$gzip.Dispose(); $input.Dispose()
[System.IO.File]::WriteAllBytes($target,[System.Text.Encoding]::UTF8.GetBytes([System.Text.Encoding]::UTF8.GetString($output.ToArray())))
$output.Dispose()
Write-Host "Complete SettingsPage.jsx replacement written to $target"
